import { strictHttpsUrl } from '../adminPinnedHttps';
import {
    METADATA_LOOKUP_HOSTS, METADATA_LOOKUP_JOB_LIMITS, METADATA_LOOKUP_LIMITS, MetadataLookupInputError,
    type LookupArtistCredit, type LookupLabel, type MusicBrainzIsrcResult, type MusicBrainzRecordingHit,
    type MusicBrainzRelease, type MusicBrainzReleaseSummary, type MusicBrainzTrack
} from './lookupContract';
import { cleanLookupTerm, normalizeGtin, normalizeIsrc, normalizeMusicBrainzId } from './lookupIdentifiers';
import { array, boolean, date, integer, lenient, object, parseLookupDate, string, validateLookupShape, type LookupShape } from './lookupResponseShape';
import { requestLookupJson, type LookupCallOptions, type LookupClientDependencies } from './lookupSourceRequest';

/**
 * MusicBrainz web-service client: Lucene field queries with every special character escaped,
 * release and ISRC lookups, release-group browse, and complete allowlisted response parsing.
 * Every identifier is format-checked before anything is sent. A release lookup keeps each track's
 * own artist credit within the release credit's bounds; an invalid one is left out for that track
 * only, so the release still parses as it did before track credits were kept. It also counts each
 * medium's pregap and data tracks, which are otherwise dropped; invalid ones are not counted.
 */
export type MusicBrainzReleaseQuery = {
    release?: string; artist?: string; label?: string; catno?: string; barcode?: string;
    tracks?: number; primarytype?: string; secondarytype?: string;
};
export type MusicBrainzRecordingQuery = { recording: string; artist?: string; release?: string };

const textFields = ['release', 'recording', 'artist', 'label', 'catno'] as const;
const primaryTypes = new Set(['album', 'single', 'ep', 'broadcast', 'other']);
const secondaryTypes = new Set(['compilation', 'soundtrack', 'spokenword', 'interview', 'audiobook', 'audio drama', 'live',
    'remix', 'dj-mix', 'mixtape/street', 'demo', 'field recording']);

/** Escapes every Lucene special character, including both halves of `&&` and `||`. */
export const escapeLucene = (text: string) => text.replace(/[+\-&|!(){}[\]^"~*?:\\/]/g, character => `\\${character}`);

/** Builds `field:"escaped"` terms joined by ` AND ` in a fixed field order, so equal queries give equal URLs. */
export const musicBrainzLuceneQuery = (query: MusicBrainzReleaseQuery | MusicBrainzRecordingQuery): string => {
    const input = query as Record<string, unknown>;
    const terms: string[] = [];
    let searchable = false;
    for (const field of textFields) {
        if (input[field] === undefined) continue;
        terms.push(`${field}:"${escapeLucene(cleanLookupTerm(input[field], METADATA_LOOKUP_LIMITS.termLength))}"`);
        searchable = true;
    }
    if (input.barcode !== undefined) {
        const gtin = normalizeGtin(input.barcode);
        if (!gtin) throw new MetadataLookupInputError('identifier');
        terms.push(`barcode:"${gtin.digits}"`);
        searchable = true;
    }
    if (input.tracks !== undefined) {
        if (!Number.isSafeInteger(input.tracks) || (input.tracks as number) < 1 || (input.tracks as number) > 9999) throw new MetadataLookupInputError('identifier');
        terms.push(`tracks:${input.tracks}`);
    }
    for (const [field, allowed] of [['primarytype', primaryTypes], ['secondarytype', secondaryTypes]] as const) {
        if (input[field] === undefined) continue;
        if (typeof input[field] !== 'string' || !allowed.has(input[field] as string)) throw new MetadataLookupInputError('identifier');
        terms.push(`${field}:"${input[field]}"`);
    }
    if (!searchable) throw new MetadataLookupInputError('empty');
    const lucene = terms.join(' AND ');
    if (lucene.length > METADATA_LOOKUP_LIMITS.queryLength) throw new MetadataLookupInputError('tooLong');
    return lucene;
};

const base = `https://${METADATA_LOOKUP_HOSTS.musicBrainz}/ws/2/`;
const withParameters = (path: string, parameters: [string, string][]) => {
    const url = new URL(path, base);
    // Space-separated `inc` values serialize as `+`, the separator MusicBrainz documents.
    for (const [name, value] of parameters) url.searchParams.append(name, value);
    return url;
};
const requireMbid = (value: unknown) => {
    const id = normalizeMusicBrainzId(value);
    if (!id) throw new MetadataLookupInputError('identifier');
    return id;
};

/** URL builders with a fixed parameter order; the fixture recorder and tests use the same ones. */
export const musicBrainzUrls = Object.freeze({
    releaseSearch: (query: MusicBrainzReleaseQuery) => withParameters('release', [['query', musicBrainzLuceneQuery(query)], ['fmt', 'json'], ['limit', String(METADATA_LOOKUP_LIMITS.releaseSearchLimit)]]),
    recordingSearch: (query: MusicBrainzRecordingQuery) => withParameters('recording', [['query', musicBrainzLuceneQuery(query)], ['fmt', 'json'], ['limit', String(METADATA_LOOKUP_LIMITS.searchLimit)]]),
    release: (releaseId: string) => withParameters(`release/${requireMbid(releaseId)}`, [['inc', 'artist-credits labels recordings release-groups isrcs'], ['fmt', 'json']]),
    releaseGroupBrowse: (releaseGroupId: string) => withParameters('release', [['release-group', requireMbid(releaseGroupId)], ['inc', 'artist-credits labels media'], ['fmt', 'json'], ['limit', String(METADATA_LOOKUP_LIMITS.browseLimit)]]),
    isrc: (isrc: string) => {
        const normalized = normalizeIsrc(isrc);
        if (!normalized) throw new MetadataLookupInputError('identifier');
        return withParameters(`isrc/${normalized}`, [['inc', 'releases'], ['fmt', 'json']]);
    },
    /** Artist and label lookups with aliases (the release lookup documents no aliases include). */
    artistAliases: (artistId: string) => withParameters(`artist/${requireMbid(artistId)}`, [['inc', 'aliases'], ['fmt', 'json']]),
    labelAliases: (labelId: string) => withParameters(`label/${requireMbid(labelId)}`, [['inc', 'aliases'], ['fmt', 'json']])
});

/** Every hop must stay on musicbrainz.org under `/ws/2/`. */
export const musicBrainzDestination = (url: URL): URL | null => {
    const strict = strictHttpsUrl(url.href);
    return strict && strict.hostname === METADATA_LOOKUP_HOSTS.musicBrainz && strict.pathname.startsWith('/ws/2/') ? strict : null;
};

const text = METADATA_LOOKUP_LIMITS.textLength;
const mbid = string(36, { pattern: /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/ });
const country = string(2, { pattern: /^[A-Z]{2}$/, nullable: true, optional: true });
const length = integer(1, 86_400_000, { nullable: true, optional: true });
const typeName = string(64, { nullable: true, optional: true });
const artistCredit = array(object({
    name: string(text),
    joinphrase: string(200, { optional: true }),
    artist: object({ id: mbid, name: string(text) })
}), 50, { optional: true });
const labelInfo = array(object({
    'catalog-number': string(200, { nullable: true, optional: true }),
    label: object({ id: mbid, name: string(text) }, { nullable: true, optional: true })
}), 50, { optional: true });
const releaseGroup = object({
    id: mbid,
    'primary-type': typeName,
    'secondary-types': array(string(64), 20, { optional: true }),
    'first-release-date': date({ optional: true })
}, { optional: true });
const releaseCommon = {
    id: mbid,
    title: string(text),
    status: typeName,
    'artist-credit': artistCredit,
    'release-group': releaseGroup,
    date: date({ optional: true, nullable: true }),
    country,
    barcode: string(64, { nullable: true, optional: true }),
    'label-info': labelInfo
};
const summaryShape = object({
    ...releaseCommon,
    score: integer(0, 100, { optional: true }),
    'track-count': integer(0, 99_999, { optional: true }),
    media: array(object({ format: typeName, 'track-count': integer(0, 9999) }), 100, { optional: true })
});

/** Allowlisted shapes; the recorder trims fixtures with these, and the parsers below accept the result. */
export const musicBrainzShapes: Readonly<Record<'releaseSearch' | 'release' | 'recordingSearch' | 'browse' | 'isrc' | 'entityAliases', LookupShape>> = Object.freeze({
    releaseSearch: object({ count: integer(0, 1_000_000_000), offset: integer(0, 1_000_000_000, { optional: true }), releases: array(summaryShape, METADATA_LOOKUP_LIMITS.releaseSearchLimit) }),
    release: object({
        ...releaseCommon,
        'cover-art-archive': object({ front: boolean() }, { optional: true }),
        media: array(object({
            position: integer(1, 999),
            format: typeName,
            // Counted as left out only: a pregap track and the data tracks MusicBrainz lists apart from `tracks`.
            pregap: lenient(object({ position: integer(0, 9999) })),
            'data-tracks': lenient(array(object({ position: integer(0, 9999) }), 999)),
            tracks: array(object({
                position: integer(1, 9999),
                number: string(32),
                title: string(text),
                length,
                recording: object({ id: mbid, length, isrcs: array(string(12, { pattern: /^[A-Z]{2}[A-Z0-9]{3}\d{7}$/ }), 100, { optional: true }) }),
                'artist-credit': lenient(artistCredit)
            }), 999, { optional: true })
        }), 100)
    }),
    recordingSearch: object({
        count: integer(0, 1_000_000_000), offset: integer(0, 1_000_000_000, { optional: true }),
        recordings: array(object({
            id: mbid, title: string(text), length, 'artist-credit': artistCredit,
            releases: array(object({
                id: mbid, title: string(text), 'track-count': integer(0, 99_999, { optional: true }),
                date: date({ optional: true, nullable: true }), country, 'release-group': releaseGroup,
                media: array(object({ position: integer(1, 999), format: typeName, 'track-offset': integer(0, 99_999, { optional: true }) }), 100, { optional: true })
            }), 100, { optional: true })
        }), 100)
    }),
    browse: object({ 'release-count': integer(0, 1_000_000_000), 'release-offset': integer(0, 1_000_000_000, { optional: true }), releases: array(summaryShape, 100) }),
    isrc: object({
        isrc: string(12, { pattern: /^[A-Z]{2}[A-Z0-9]{3}\d{7}$/ }),
        recordings: array(object({ id: mbid, title: string(text), length, releases: array(object({ id: mbid }), 100, { optional: true }) }), 100)
    }),
    entityAliases: object({
        id: mbid, name: string(text),
        aliases: array(object({ name: string(text), type: typeName, primary: boolean({ nullable: true, optional: true }) }), 1000, { optional: true })
    })
});

type RawCredit = { name: string; joinphrase?: string; artist: { id: string; name: string } };
type RawLabelInfo = { 'catalog-number'?: string | null; label?: { id: string; name: string } | null };
type RawGroup = { id: string; 'primary-type'?: string | null; 'secondary-types'?: string[]; 'first-release-date'?: string };
type RawReleaseCommon = { id: string; title: string; status?: string | null; 'artist-credit'?: RawCredit[]; 'release-group'?: RawGroup;
    date?: string | null; country?: string | null; barcode?: string | null; 'label-info'?: RawLabelInfo[] };
type RawSummary = RawReleaseCommon & { score?: number; 'track-count'?: number; media?: { format?: string | null; 'track-count': number }[] };
type RawRelease = RawReleaseCommon & { 'cover-art-archive'?: { front: boolean };
    media: { position: number; format?: string | null; pregap?: { position: number }; 'data-tracks'?: { position: number }[];
        tracks?: { position: number; number: string; title: string; length?: number | null;
        recording: { id: string; length?: number | null; isrcs?: string[] }; 'artist-credit'?: RawCredit[] }[] }[] };

const credits = (raw: RawCredit[] | undefined): LookupArtistCredit[] => (raw ?? []).map(credit => ({
    name: credit.name, joinPhrase: credit.joinphrase ?? '', artistId: credit.artist.id, artistName: credit.artist.name
}));
const labels = (raw: RawLabelInfo[] | undefined): LookupLabel[] => (raw ?? []).map(info => ({
    name: info.label?.name ?? null, labelId: info.label?.id ?? null, catalogNumber: info['catalog-number'] ?? null
}));
const common = (raw: RawReleaseCommon) => ({
    releaseId: raw.id, releaseGroupId: raw['release-group']?.id ?? null, title: raw.title, status: raw.status ?? null,
    artistCredit: credits(raw['artist-credit']), labels: labels(raw['label-info']),
    // A malformed or all-zero barcode is no barcode for comparisons; its raw text stays evidence.
    barcode: normalizeGtin(raw.barcode)?.digits ?? null, barcodeText: raw.barcode ?? null,
    country: raw.country ?? null, date: parseLookupDate(raw.date),
    primaryType: raw['release-group']?.['primary-type'] ?? null, secondaryTypes: [...(raw['release-group']?.['secondary-types'] ?? [])]
});
const summary = (raw: RawSummary): MusicBrainzReleaseSummary => {
    const media = (raw.media ?? []).map(medium => ({ format: medium.format ?? null, trackCount: medium['track-count'] }));
    return { ...common(raw), trackCount: raw['track-count'] ?? media.reduce((sum, medium) => sum + medium.trackCount, 0), media, score: raw.score ?? null };
};

export const parseMusicBrainzReleaseSearch = (json: unknown) => {
    const raw = validateLookupShape<{ count: number; releases: RawSummary[] }>(musicBrainzShapes.releaseSearch, json);
    return { count: raw.count, releases: raw.releases.map(summary) };
};

export const parseMusicBrainzBrowse = (json: unknown): MusicBrainzReleaseSummary[] =>
    validateLookupShape<{ releases: RawSummary[] }>(musicBrainzShapes.browse, json).releases.map(summary);

export const parseMusicBrainzRelease = (json: unknown): MusicBrainzRelease => {
    const raw = validateLookupShape<RawRelease>(musicBrainzShapes.release, json);
    const media = raw.media.map(medium => {
        // Absent when none, so a release without pregap or data tracks parses and stores as before they were counted.
        const hiddenTracks = (medium.pregap ? 1 : 0) + (medium['data-tracks']?.length ?? 0);
        return {
            position: medium.position, format: medium.format ?? null,
            tracks: (medium.tracks ?? []).map((track): MusicBrainzTrack => ({
                position: track.position, number: track.number, title: track.title,
                lengthMs: track.length ?? track.recording.length ?? null, recordingId: track.recording.id, isrcs: [...(track.recording.isrcs ?? [])],
                ...(track['artist-credit'] === undefined ? {} : { artistCredit: credits(track['artist-credit']) })
            })),
            ...(hiddenTracks ? { hiddenTracks } : {})
        };
    });
    return {
        ...common(raw), trackCount: media.reduce((sum, medium) => sum + medium.tracks.length, 0), media,
        groupFirstReleaseDate: parseLookupDate(raw['release-group']?.['first-release-date']),
        frontArtwork: raw['cover-art-archive']?.front ?? null
    };
};

export const parseMusicBrainzRecordingSearch = (json: unknown) => {
    type RawHit = { id: string; title: string; length?: number | null; 'artist-credit'?: RawCredit[]; releases?: { id: string; title: string;
        'track-count'?: number; date?: string | null; country?: string | null; 'release-group'?: RawGroup;
        media?: { position: number; format?: string | null; 'track-offset'?: number }[] }[] };
    const raw = validateLookupShape<{ count: number; recordings: RawHit[] }>(musicBrainzShapes.recordingSearch, json);
    return {
        count: raw.count,
        recordings: raw.recordings.map((hit): MusicBrainzRecordingHit => ({
            recordingId: hit.id, title: hit.title, lengthMs: hit.length ?? null, artistCredit: credits(hit['artist-credit']),
            releases: (hit.releases ?? []).map(release => ({
                releaseId: release.id, title: release.title, trackCount: release['track-count'] ?? null,
                media: (release.media ?? []).map(medium => ({ position: medium.position, format: medium.format ?? null, trackOffset: medium['track-offset'] ?? null })),
                date: parseLookupDate(release.date), country: release.country ?? null,
                primaryType: release['release-group']?.['primary-type'] ?? null, secondaryTypes: [...(release['release-group']?.['secondary-types'] ?? [])]
            }))
        }))
    };
};

export const parseMusicBrainzIsrc = (json: unknown): MusicBrainzIsrcResult => {
    const raw = validateLookupShape<{ isrc: string; recordings: { id: string; title: string; length?: number | null; releases?: { id: string }[] }[] }>(musicBrainzShapes.isrc, json);
    return { isrc: raw.isrc, recordings: raw.recordings.map(recording => ({
        recordingId: recording.id, title: recording.title, lengthMs: recording.length ?? null, releaseIds: (recording.releases ?? []).map(release => release.id)
    })) };
};

const aliasInvisible = /[\p{Cc}\p{Cf}\p{Cs}]/u;
/**
 * An artist's or label's names from a lookup with aliases, or null when MusicBrainz answered for another ID (a merged entity):
 * the entity name, then primary aliases, then the others, each group in folded-name order (MusicBrainz documents aliases as an
 * unordered set), deduplicated by folded name, NFC and trimmed, at most 200 characters without control or invisible characters,
 * and at most `METADATA_LOOKUP_JOB_LIMITS.aliasNames`. Search hints are excluded: MusicBrainz documents them as misspellings.
 */
export const parseMusicBrainzEntityAliases = (json: unknown, requestedId: string): { id: string; names: string[] } | null => {
    const raw = validateLookupShape<{ id: string; name: string; aliases?: { name: string; type?: string | null; primary?: boolean | null }[] }>(musicBrainzShapes.entityAliases, json);
    if (raw.id !== normalizeMusicBrainzId(requestedId)) return null;
    const clean = (value: string) => { const name = value.normalize('NFC').trim(); return name && name.length <= 200 && !aliasInvisible.test(name) ? name : null; };
    const fold = (value: string) => value.toLowerCase();
    const aliases = (raw.aliases ?? []).filter(alias => (alias.type ?? '').toLowerCase() !== 'search hint');
    const sorted = (primary: boolean) => aliases.filter(alias => (alias.primary === true) === primary).map(alias => clean(alias.name)).filter((name): name is string => name !== null)
        .sort((left, right) => fold(left) < fold(right) ? -1 : fold(left) > fold(right) ? 1 : left < right ? -1 : left > right ? 1 : 0);
    const names: string[] = [];
    for (const name of [clean(raw.name), ...sorted(true), ...sorted(false)]) {
        if (names.length >= METADATA_LOOKUP_JOB_LIMITS.aliasNames) break;
        if (name && !names.some(existing => fold(existing) === fold(name))) names.push(name);
    }
    return { id: raw.id, names };
};

export interface MusicBrainzClient {
    searchReleases(query: MusicBrainzReleaseQuery, options: LookupCallOptions): Promise<{ count: number; releases: MusicBrainzReleaseSummary[] }>;
    searchRecordings(query: MusicBrainzRecordingQuery, options: LookupCallOptions): Promise<{ count: number; recordings: MusicBrainzRecordingHit[] }>;
    /** Null when MusicBrainz answers 404. */
    lookupRelease(releaseId: string, options: LookupCallOptions): Promise<MusicBrainzRelease | null>;
    browseReleaseGroupReleases(releaseGroupId: string, options: LookupCallOptions): Promise<MusicBrainzReleaseSummary[]>;
    /** Null when MusicBrainz answers 404. */
    lookupIsrc(isrc: string, options: LookupCallOptions): Promise<MusicBrainzIsrcResult | null>;
    /** An artist's or label's names (parseMusicBrainzEntityAliases); null when MusicBrainz answers 404 or for another ID. */
    lookupAliases(kind: 'artist' | 'label', id: string, options: LookupCallOptions): Promise<{ id: string; names: string[] } | null>;
}

const requestBase = {
    source: 'musicbrainz' as const, destination: musicBrainzDestination, accept: 'application/json', contentTypes: ['application/json'],
    maximumBytes: METADATA_LOOKUP_LIMITS.musicBrainzBytes, deadlineMs: METADATA_LOOKUP_LIMITS.requestDeadlineMs.musicbrainz,
    rateLimitStatuses: [429, 503]
};

export const createMusicBrainzClient = (dependencies: LookupClientDependencies): MusicBrainzClient => ({
    async searchReleases(query, options) {
        const url = musicBrainzUrls.releaseSearch(query);
        return requestLookupJson({ ...requestBase, url, emptyStatuses: [], emptyValue: { count: 0, releases: [] }, parse: parseMusicBrainzReleaseSearch }, options, dependencies);
    },
    async searchRecordings(query, options) {
        const url = musicBrainzUrls.recordingSearch(query);
        return requestLookupJson({ ...requestBase, url, emptyStatuses: [], emptyValue: { count: 0, recordings: [] }, parse: parseMusicBrainzRecordingSearch }, options, dependencies);
    },
    async lookupRelease(releaseId, options) {
        const url = musicBrainzUrls.release(releaseId);
        return requestLookupJson<MusicBrainzRelease | null>({ ...requestBase, url, emptyStatuses: [404], emptyValue: null, parse: parseMusicBrainzRelease }, options, dependencies);
    },
    async browseReleaseGroupReleases(releaseGroupId, options) {
        const url = musicBrainzUrls.releaseGroupBrowse(releaseGroupId);
        return requestLookupJson<MusicBrainzReleaseSummary[]>({ ...requestBase, url, emptyStatuses: [], emptyValue: [], parse: parseMusicBrainzBrowse }, options, dependencies);
    },
    async lookupIsrc(isrc, options) {
        const url = musicBrainzUrls.isrc(isrc);
        return requestLookupJson<MusicBrainzIsrcResult | null>({ ...requestBase, url, emptyStatuses: [404], emptyValue: null, parse: parseMusicBrainzIsrc }, options, dependencies);
    },
    async lookupAliases(kind, id, options) {
        const url = kind === 'artist' ? musicBrainzUrls.artistAliases(id) : musicBrainzUrls.labelAliases(id);
        return requestLookupJson<{ id: string; names: string[] } | null>({ ...requestBase, url, emptyStatuses: [404], emptyValue: null,
            parse: json => parseMusicBrainzEntityAliases(json, id) }, options, dependencies);
    }
});
